public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Filter out null strings and ensure at least one non-empty string
    List<String> nonNull = new java.util.ArrayList<>();
    for (String s : strings) {
        if (s != null) {
            nonNull.add(s);
        }
    }
    if (nonNull.isEmpty()) {
        return 0;
    }

    // Find the shortest string to limit substring candidates
    String minS = null;
    int minLen = Integer.MAX_VALUE;
    for (String s : nonNull) {
        if (s.length() < minLen) {
            minLen = s.length();
            minS = s;
        }
    }
    if (minS == null || minLen == 0) {
        return 0;
    }

    // Iterate possible lengths from longest to shortest
    for (int len = minLen; len >= 1; len--) {
        // Use a set to avoid duplicate substrings for this length
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        for (int start = 0; start <= minS.length() - len; start++) {
            String sub = minS.substring(start, start + len);
            if (!seen.add(sub)) continue; // skip duplicates

            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (String s : nonNull) {
                if (!s.contains(sub) && !s.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len; // longest found
            }
        }
    }
    return 0; // No substring found
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    final int n = strings.size();
    // Map from canonical substring (lexicographically smallest between substring and its reverse)
    // to a bitmask indicating which strings contain it (directly or as reverse).
    java.util.HashMap<String, Long> map = new java.util.HashMap<>();
    for (int idx = 0; idx < n; idx++) {
        String s = strings.get(idx);
        if (s == null) {
            s = "";
        }
        int len = s.length();
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        for (int start = 0; start < len; start++) {
            for (int end = start + 1; end <= len; end++) {
                String sub = s.substring(start, end);
                String rev = new StringBuilder(sub).reverse().toString();
                String canon = (rev.compareTo(sub) < 0) ? rev : sub;
                seen.add(canon);
            }
        }
        long bit = 1L << idx;
        for (String canon : seen) {
            map.merge(canon, bit, (oldVal, newVal) -> oldVal | newVal);
        }
    }

    int bestLen = 0;
    for (java.util.Map.Entry<String, Long> entry : map.entrySet()) {
        if (Long.bitCount(entry.getValue()) >= 2) {
            int currLen = entry.getKey().length();
            if (currLen > bestLen) {
                bestLen = currLen;
            }
        }
    }
    return bestLen;
}

