public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("N must be non-negative");
    }
    if (N == 0) {
        return 1; // no triangle divides the plane into 1 region
    }
    long n = N;
    long regions = n * n * n - n + 2;
    if (regions > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds int range");
    }
    return (int) regions;
}

