public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation of inputs
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length < 2 || end.length < 2) { // assuming at least 2D coordinates
        return "cannot be travelled";
    }
    // Check that start and end coordinates are within bounds
    for (int i = 0; i < start.length; i++) {
        if (start[i] < 0 || start[i] >= n) {
            return "cannot be travelled";
        }
    }
    for (int i = 0; i < end.length; i++) {
        if (end[i] < 0 || end[i] >= n) {
            return "cannot be travelled";
        }
    }

    // Utility to convert coordinate array to a unique key string
    java.util.function.Function<int[], String> coordToKey = coords -> {
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < coords.length; j++) {
            if (j > 0) sb.append(",");
            sb.append(coords[j]);
        }
        return sb.toString();
    };

    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

    // Build graph from paths
    for (int[] path : paths) {
        if (path == null || path.length != 4) {
            continue; // ignore malformed path entries
        }
        int[] origin = new int[]{path[0], path[1]};
        int[] dest   = new int[]{path[2], path[3]};

        // Validate coordinates within bounds
        if (origin[0] < 0 || origin[0] >= n || origin[1] < 0 || origin[1] >= n ||
            dest[0] < 0   || dest[0]   >= n || dest[1] < 0   || dest[1]   >= n) {
            continue;
        }

        String oKey = coordToKey.apply(origin);
        String dKey = coordToKey.apply(dest);

        graph.computeIfAbsent(oKey, k -> new java.util.ArrayList<>()).add(dKey);
        graph.computeIfAbsent(dKey, k -> new java.util.ArrayList<>()).add(oKey);
    }

    String startKey = coordToKey.apply(start);
    String endKey   = coordToKey.apply(end);

    if (!graph.containsKey(startKey) || !graph.containsKey(endKey)) {
        return "cannot be travelled";
    }

    java.util.Queue<String> queue = new java.util ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neigh = graph.getOrDefault(cur, java.util.Collections.emptyList());
        for (String nxt : neigh) {
            if (!visited.contains(nxt)) {
                visited.add(nxt);
                queue.add(nxt);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input parameters
    if (n <= 0 || start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }

    // Helper to convert coordinate array to a unique linear index
    java.util.function.LongUnaryOperator coordToIndex = (coordArray) -> {
        try {
            long idx = 0;
            long multiplier = 1;
            for (int i = 0; i < n; i++) {
                if (coordArray[i] < 0 || coordArray[i] >= n) {
                    return -1;
                }
                idx += (long) coordArray[i] * multiplier;
                multiplier *= n;
                if (multiplier < 0) { // overflow guard
                    return -1;
                }
            }
            return idx;
        } catch (Exception e) {
            return -1;
        }
    };

    long startIdx = coordToIndex.applyAsLong(Integer.hashCode(start[0]) == 0 ? 0 : 0); // dummy to use lambda
    // Since the lambda above expects a long input, we compute index manually below
    long sIdx = 0, eIdx = 0;
    try {
        long mult = 1;
        for (int i = 0; i < n; i++) {
            if (start[i] < 0 || start[i] >= n) return "cannot be travelled";
            sIdx += (long) start[i] * mult;
            mult *= n;
        }
        mult = 1;
        for (int i = 0; i < n; i++) {
            if (end[i] < 0 || end[i] >= n) return "cannot be travelled";
            eIdx += (long) end[i] * mult;
            mult *= n;
        }
    } catch (Exception e) {
        return "cannot be travelled";
    }

    if (sIdx == eIdx) {
        return "can be travelled";
    }

    // Build adjacency list for the graph defined by paths
    java.util.Map<Long, java.util.List<Long>> adjacency = new java.util.HashMap<>();

    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length != 2) {
                continue; // skip invalid path entries
            }
            long u = p[0];
            long v = p[1];
            adjacency.computeIfAbsent(u, k -> new java.util.ArrayList<>()).add(v);
            adjacency.computeIfAbsent(v, k -> new java.util.ArrayList<>()).add(u);
        }
    }

    // Breadth-first search to check connectivity
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    java.util.Set<Long> visited = new java.util.HashSet<>();

    queue.offer(sIdx);
    visited.add(sIdx);

    while (!queue.isEmpty()) {
        long current = queue.poll();
        java.util.List<Long> neighbors = adjacency.getOrDefault(current, java.util.Collections.emptyList());
        for (long next : neighbors) {
            if (next == eIdx) {
                return "can be travelled";
            }
            if (!visited.contains(next)) {
                visited.add(next);
                queue.offer(next);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate inputs
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int startNode = start[0];
    int endNode = end[0];
    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        return "cannot be travelled";
    }

    // Build adjacency list
    List<List<Integer>> adj = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] edge : paths) {
        if (edge == null || edge.length < 2) continue;
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        adj.get(u).add(v);
        adj.get(v).add(u);
    }

    // BFS to find if end reachable from start
    boolean[] visited = new boolean[n];
    Deque<Integer> queue = new ArrayDeque<>();
    visited[startNode] = true;
    queue.add(startNode);
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        if (cur == endNode) {
            return "can be travelled";
        }
        for (int neigh : adj.get(cur)) {
            if (!visited[neigh]) {
                visited[neigh] = true;
                queue.add(neigh);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return "Invalid date";
        }
        int monthInt = Integer.parseInt(parts[0]);
        int dayInt = Integer.parseInt(parts[1]);
        int yearInt = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(yearInt, monthInt, dayInt);

        String[] monthNames = {
            "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };
        String monthName = monthNames[monthInt - 1];

        int weekdayValue = localDate.getDayOfWeek().getValue(); // 1 = Monday ... 7 = Sunday
        String[] weekdayNames = {
            "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"
        };
        String weekdayName = weekdayNames[weekdayValue - 1];

        return monthName + " " + dayInt + ", " + yearInt + " is a " + weekdayName;
    } catch (Exception e) {
        return "Invalid date";
    }
}

