public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int trim = (int) Math.floor(n * 0.05);
    int start = trim;
    int end = n - 1 - trim;
    if (start > end) {
        return 0.0;
    }
    java.util.Arrays.sort(arr);
    long sum = 0L;
    for (int i = start; i <= end; i++) {
        sum += arr[i];
    }
    int count = end - start + 1;
    return sum / (double) count;
}

public double trimMean(int[] arr) {
    // Handle null or empty input
    if (arr == null || arr.length == 0) {
        return 0.0;
    }

    int n = arr.length;
    // Determine how many elements to trim from each side (5% of n)
    int k = (int) Math.floor(n * 0.05);

    // Sort the array in ascending order
    java.util.Arrays.sort(arr);

    // Sum the remaining elements after trimming
    long sum = 0;
    int start = k;
    int end = n - k; // exclusive
    int count = end - start;

    // Guard against division by zero, though count should be > 0
    if (count <= 0) {
        return 0.0;
    }

    for (int i = start; i < end; i++) {
        sum += arr[i];
    }

    // Compute and return the mean
    return sum / (double) count;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
