    try {
        java.util.Arrays.sort(arr);
    } catch (Exception e) {
        // In case sorting fails, return 0.0 as a fallback
        return 0.0;
    }
    long sum = 0L;
    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    double remaining = n - 2L * k;
    if (remaining <= 0) {
        return 0.0;
    }
    return (double) sum / remaining;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int remove = (int) Math.floor(n * 0.05);
    if (remove == 0) {
        remove = (int) Math.floor(n * 0.05 + 1e-9); // handle floating precision
    }
    if (remove == 0) {
        // If still zero after correction, no trimming needed
        long total = 0L;
        for (int v : arr) {
            total += v;
        }
        return (double) total / n;
    }
    try {
        java.util.Arrays.sort(arr);
    } catch (OutOfMemoryError e) {
        // Fallback: use a copy with limited size
        int[] temp = new int[n];
        System.arraycopy(arr, 0, temp, 0, n);
        java.util.Arrays.sort(temp);
        arr = temp;
    }
    int start = remove;
    int end = n - remove; // exclusive
    if (start >= end) {
        return 0.0;
    }
    long sum = 0L;
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }
    return (double) sum / (end - start);
}

public double trimMean(int[] arr) {
