    for (int i = trimCount; i < n - trimCount; i++) {
        sum += arr[i];
    }
    int remaining = n - 2 * trimCount;
    if (remaining <= 0) {
        return 0.0;
    }
    return sum / (double) remaining;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("Divisor k must be positive");
    }
    if (arr.length % 2 != 0) {
        return false; // cannot pair all elements
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k; // ensure non‑negative remainder
        }
        freq[r] += 1;
    }

    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }

    // If k is even, remainder k/2 must also have even frequency
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }

    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled when k is even
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

