        }
        freq[rem]++;
    }
    // Remainder 0 must pair among themselves
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must pair among themselves
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // Check all other remainders i and k-i
    for (int i = 1; i <= k / 2; i++) {
        if (k % 2 == 0 && i == k / 2) {
