public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || arr.length == 0) return false;
    if (k <= 0) return false; // divisor must be positive
    if ((arr.length & 1) == 1) return false; // odd length cannot be fully paired

    // Count remainders
    int[] remainderCount = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) rem += k; // ensure non-negative remainder
        remainderCount[rem]++;
    }

    // Check pairs
    // Remainder 0 should be even
    if (remainderCount[0] % 2 != 0) return false;

    // If k is even, remainder k/2 should also be even
    if ((k & 1) == 0) {
        if (remainderCount[k / 2] % 2 != 0) return false;
    }

    // For other remainders, counts should match complementary remainders
    for (int r = 1; r * 2 < k; r++) {
        if (remainderCount[r] != remainderCount[k - r]) return false;
    }

    return true;
}

