        return false;
    }
    // handle remainders
    for (int r = 1; r < freq.length; r++) {
        int complement = k - r;
        if (complement == r) { // when k even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

