public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) return 0;
    if (edges == null) throw new IllegalArgumentException("edges is null");
    if (edges.length != n - 1) throw new IllegalArgumentException("edges length must be n-1");
    if (hasApple == null || hasApple.length != n) throw new IllegalArgumentException("hasApple size invalid");
    java.util.List<java.util.ArrayList<Integer>> graph = new java.util.ArrayList<>(n);
    for (int i = 0; i < n; i++) graph.add(new java.util.ArrayList<Integer>());
    for (int[] e : edges) {
        if (e == null || e.length != 2) throw new IllegalArgumentException("Each edge must have two nodes");
        int u = e[0], v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) throw new IllegalArgumentException("Node index out of bounds");
        graph.get(u).add(v);
        graph.get(v).add(u);
    }
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx = 0;
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        java.util.List<Integer> neighbors = graph.get(node);
        for (int nei : neighbors) {
            if (nei != parent[node]) {
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }
    boolean[] hasSubtree = new boolean[n];
    int result = 0;
    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        boolean has = hasApple[node];
        java.util.List<Integer> neighbors = graph.get(node);
        for (int nei : neighbors) {
            if (nei == parent[node]) continue;
            if (hasSubtree[nei]) {
                result += 2;
                has = true;
            }
        }
        hasSubtree[node] = has;
    }
    return result;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[65536];
    for (char c : s.toCharArray()) {
        freq[c]++;
    }
    int remaining = s.length();
    StringBuilder sb = new StringBuilder(remaining);
    while (remaining > 0) {
        // Ascending pass
        int minIdx = -1;
        for (int i = 0; i < 65536 && minIdx == -1; i++) {
            if (freq[i] > 0) {
                minIdx = i;
            }
        }
        if (minIdx == -1) {
            break;
        }
        sb.append((char) minIdx);
        freq[minIdx]--;
        remaining--;
        int last = minIdx;
        while (remaining > 0) {
            int next = -1;
            for (int i = last + 1; i < 65536; i++) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            sb.append((char) next);
            freq[next]--;
            remaining--;
            last = next;
        }
        if (remaining == 0) {
            break;
        }
        // Descending pass
        int maxIdx = -1;
        for (int i = 65535; i >= 0 && maxIdx == -1; i--) {
            if (freq[i] > 0) {
                maxIdx = i;
            }
        }
        if (maxIdx == -1) {
            break;
        }
        sb.append((char) maxIdx);
        freq[maxIdx]--;
        remaining--;
        last = maxIdx;
        while (remaining > 0) {
            int prev = -1;
            for (int i = last - 1; i >= 0; i--) {
                if (freq[i] > 0) {
                    prev = i;
                    break;
                }
            }
            if (prev == -1) {
                break;
            }
            sb.append((char) prev);
            freq[prev]--;
            remaining--;
            last = prev;
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    if (s.isEmpty()) {
        return "";
    }

    final int ALPHABET_SIZE = 65536; // Unicode
    int[] freq = new int[ALPHABET_SIZE];
    int total = 0;
    for (char c : s.toCharArray()) {
        freq[c]++;
        total++;
    }

    StringBuilder sb = new StringBuilder(total);

    while (total > 0) {
        /* Ascending phase */
        int last = -1;
        for (int ch = 0; ch < ALPHABET_SIZE && total > 0; ch++) {
            if (freq[ch] > 0 && ch > last) {
                sb.append((char) ch);
                freq[ch]--;
                total--;
                last = ch;
            }
        }
        if (total == 0) {
            break;
        }

        /* Descending phase */
        int start = -1;
        for (int ch = ALPHABET_SIZE - 1; ch >= 0 && total > 0; ch--) {
            if (freq[ch] > 0) {
                sb.append((char) ch);
                freq[ch]--;
                total--;
                start = ch;
                break;
            }
        }
        if (total == 0) {
            break;
        }

        for (int ch = start - 1; ch >= 0 && total > 0; ch--) {
            if (freq[ch] > 0) {
                sb.append((char) ch);
                freq[ch]--;
                total--;
            }
        }
    }

    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    final int MAX_CHAR = Character.MAX_VALUE; // 65535
    int[] freq = new int[MAX_CHAR + 1];
    for (int i = 0; i < s.length(); i++) {
        freq[s.charAt(i)]++;
    }
    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Step 1-3: increasing pass
        for (int c = 0; c <= MAX_CHAR && remaining > 0; c++) {
            if (freq[c] > 0) {
                result.append((char) c);
                freq[c]--;
                remaining--;
            }
        }
        // Step 4-6: decreasing pass
        for (int c = MAX_CHAR; c >= 0 && remaining > 0; c--) {
            if (freq[c] > 0) {
                result.append((char) c);
                freq[c]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int total = 0;
    for (int v : nums) total += v;
    int half = n / 2;
    // sets[k] holds all possible sums of subsets with size k
    java.util.List<java.util.Set<Integer>> sets = new java.util.ArrayList<>(half + 1);
    for (int i = 0; i <= half; i++) {
        sets.add(new java.util.HashSet<>());
    }
    sets.get(0).add(0);
    for (int idx = 0; idx < n; idx++) {
        int val = nums[idx];
        // iterate k backwards to avoid reuse of current val in same iteration
        int maxK = Math.min(half, idx + 1);
        for (int k = maxK; k >= 1; k--) {
            java.util.Set<Integer> prev = sets.get(k - 1);
            java.util.Set<Integer> curr = sets.get(k);
            for (int s : prev) {
                curr.add(s + val);
            }
        }
    }
    for (int k = 1; k <= half; k++) {
        long lhs = (long) total * k;
        if (lhs % n != 0) continue;
        int target = (int) (lhs / n);
        if (sets.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

