    for (int num : nums) {
        total += num;
    }
    // DP table: dp[k][s] == true if a subset of size k with sum s exists
    // range of sums: 0..total (assuming non‑negative numbers)
    boolean[][] dp = new boolean[n + 1][total + 1];
    dp[0][0] = true;
    for (int num : nums) {
        for (int k = n; k >= 1; k--) {
            for (int s = total; s >= num; s--) {
                if (dp[k - 1][s - num]) {
                    dp[k][s] = true;
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((total * k) % n != 0) {
            continue; // average would be fractional
        }
        int target = (total * k) / n;
        if (dp[k][target]) {
            return true;
        }
    }
    return false;
}

