    int n = nums.length;
    int sum = 0;
    for (int v : nums) {
        sum += v;
    }
    // dp[k] contains all achievable sums using k elements
    java.util.List<java.util.Set<Integer>> dp = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new java.util.HashSet<>());
    }
    dp.get(0).add(0);
    for (int val : nums) {
        for (int k = n - 1; k >= 0; k--) {
            if (dp.get(k).isEmpty()) continue;
            for (int s : dp.get(k)) {
                dp.get(k + 1).add(s + val);
            }
        }
    }
    for (int k = 1; k < n; k++) {
        if ((long) sum * k % n != 0) continue;
        int target = (int) ((long) sum * k / n);
        if (dp.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int v : nums) totalSum += v;

    @SuppressWarnings("unchecked")
    Set<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new HashSet<>();
    dp[0].add(0);

    for (int v : nums) {
        for (int k = n - 1; k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + v);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        long targetTimesN = (long) totalSum * k;
        if (targetTimesN % n != 0) continue;
        int target = (int) (targetTimesN / n);
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    // dp[i] represents the minimum cost to reach step i
    int[] dp = new int[n + 1];
    // dp[0] and dp[1] are initialized to 0 by default,
    // representing the option to start at step 0 or step 1 without paying cost.
    for (int i = 2; i <= n; i++) {
        int fromOne = dp[i - 1] + cost[i - 1];
        int fromTwo = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(fromOne, fromTwo);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    try {
        if (cost == null || cost.length == 0) {
            return 0;
        }
        int n = cost.length;
        // dp0: min cost to reach step i-2
        // dp1: min cost to reach step i-1
        int dp0 = 0; // min cost to reach step -1 (the ground before step 0)
        int dp1 = 0; // min cost to reach step 0
        for (int i = 2; i <= n; i++) {
            int newCost = Math.min(dp0 + cost[i - 2], dp1 + cost[i - 1]);
            dp0 = dp1;
            dp1 = newCost;
        }
        // The top is reachable from the last or second last steps
        return Math.min(dp0, dp1);
    } catch (Exception e) {
        // In case of unexpected runtime issues, return 0 as a fallback
        return 0;
    }
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        throw new IllegalArgumentException("Input array cannot be empty");
    }
    long dpPrev2 = 0; // dp[i-2]
    long dpPrev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        long next = Math.min(dpPrev1 + cost[i - 1], dpPrev2 + cost[i - 2]);
        dpPrev2 = dpPrev1;
        dpPrev1 = next;
    }
    return (int) dpPrev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }
    int prevPrev = cost[0];          // DP[0]
    int prev = cost[1];              // DP[1]
    int curr = 0;
    for (int i = 2; i < n; i++) {
        curr = cost[i] + Math.min(prev, prevPrev);
        prevPrev = prev;
        prev = curr;
    }
    // cost to reach the top: min cost from step n-1 or n-2
    return Math.min(prev, prevPrev);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return Math.min(0, cost[0]); // only one step, best to start at top
    }

    int prevPrev = cost[0];
    int prev = cost[1];

    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev, prevPrev);
        prevPrev = prev;
        prev = current;
    }

    return Math.min(prev, prevPrev);
}

