public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (k < 0) {
        throw new IllegalArgumentException("k must be non-negative");
    }
    // Special case: k == 0 -> every binary string of length 0 (the empty string) is trivially present
    if (k == 0) {
        return true;
    }

    int n = s.length();
    // If k is too large, 2^k exceeds reasonable bounds for storage and string length.
    // For practicality, we limit k to 20 (2^20 = 1,048,576), which is sufficient for usual constraints.
    if (k > 20) {
        // Early check: even the minimal possible length to contain all codes is 2^k + k - 1.
        // If s is shorter than that, it cannot contain all codes.
        // We use long to avoid overflow.
        long minLen = ((1L << k) + k - 1);
        if (n < minLen) {
            return false;
        }
        // For k > 20 and s length sufficient, storing all patterns is infeasible.
        // Decline to compute and return false to avoid excessive memory usage.
        return false;
    }

    int totalCodes = 1 << k;                 // total distinct binary strings of length k
    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;
    int mask = totalCodes - 1;               // to keep only the last k bits

    int current = 0;
    for (int i = 0; i < n; i++) {
        current = ((current << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {                    // a complete window of length k is achieved
            if (!seen[current]) {
                seen[current] = true;
                seenCount++;
                if (seenCount == totalCodes) {
                    return true;             // all codes seen early
                }
            }
        }
    }
    return seenCount == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) {
