        Set<String> seen = new HashSet<>(totalCodes);
        for (int i = 0; i <= s.length() - k; i++) {
            seen.add(s.substring(i, i + k));
            if (seen.size() == totalCodes) {
                return true;
            }
        }
        return false;
    } catch (ArithmeticException e) {
        // In case k is too large to shift safely
        // Use logarithmic check to avoid overflow
        long totalCodes = 1L << k;
        if (totalCodes > Integer.MAX_VALUE) {
            return false;
        }
        Set<String> seen = new HashSet<>((int) totalCodes);
        for (int i = 0; i <= s.length() - k; i++) {
