            if (seen.size() == totalCodes) {
                return true;
            }
        }
        return false;
    } catch (Exception e) {
        return false;
    }
}

public boolean hasAllCodes(String s, int k) {
    // Validate inputs
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }

    // To avoid excessive memory usage, handle large k early
    if (k > 20) {
        // If s cannot possibly contain all codes of length k, return false.
        // Required minimum length: 2^k + k - 1
        long required = ((long)1 << k) + k - 1;
        if (n < required) {
            return false;
        }
        // For k > 20, the number of possible codes is too large to store efficiently.
        // Since we already tested the length condition, we can return true if length condition passes,
        // but practically this scenario is unlikely given typical constraints.
        // We'll attempt a bitset using a long array if memory permits.
        // However, for simplicity and safety, we will return false here to avoid OOM.
        return false;
    }

    int totalCodes = 1 << k;          // 2^k
    boolean[] seen = new boolean[totalCodes];
    int count = 0;
    int mask = totalCodes - 1;

    // Build initial code from first k characters
    int code = 0;
    for (int i = 0; i < k; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            return false; // Non-binary character found
        }
        code = (code << 1) | (c - '0');
    }
    seen[code] = true;
    count = 1;

    // Slide over the string
    for (int i = k; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            return false; // Non-binary character found
        }
        code = ((code << 1) & mask) | (c - '0');
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == totalCodes) {
                return true; // All codes found early
            }
        }
    }
    return count == totalCodes;
}

