public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int leftNeeded = 0;   // number of '(' needed to balance encountered ')'
    int rightNeeded = 0;  // number of ')' needed to close open '('

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            rightNeeded++;          // one more ')' needed to close this '('
        } else if (c == ')') {
            if (rightNeeded > 0) {
                rightNeeded--;     // this ')' matches a previous '('
            } else {
                leftNeeded++;       // this ')' needs an inserted '(' before it
            }
        }
    }

    return leftNeeded + rightNeeded;
}

public int minInsertions(String s) {
    if (s == null || s.isEmpty()) return 0;
    int open = 0; // number of unmatched '('
    int insertions = 0; // number of '(' inserted to balance preceding ')'
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == '(') {
            open++;
        } else if (ch == ')') {
            if (open == 0) {
                // need an opening bracket before this ')'
                insertions++;
                open = 1; // treat as if '(' was inserted and then matched
            } else {
                open--; // match with an existing '('
            }
        } else {
            // according to problem constraints, this should not happen
            // but we can ignore or throw an exception depending on policy
            // Here we simply ignore unexpected characters
        }
    }
    // All remaining unmatched '(' need a ')' each
    return insertions + open;
}

