public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    long ops = (long) n * (long) n / 4;
    return (int) ops;
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    int start = (n + 1) / 2;                 // ceil(n/2)
    long operations = (long) start * (n - start);
    return (int) operations;
}

public int minOperations(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long start = ((long)n + 1) / 2; // ceil(n/2)
    long k = (long)n - start;
    long ops = start * k;
    return (int) ops;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (n % 2 == 0) {
        long k = n / 2L;
        long result = k * k;
        return (int) result;
    } else {
        long k = n / 2L; // floor division for odd n
        long result = k * (k + 1);
        return (int) result;
    }
}

public int minOperations(int n) {
    if (n <= 0) {
