    int limit = (int) Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    }
    int remaining = k - small.size();
    if (remaining <= large.size()) {
        return large.get(large.size() - remaining);
    }
    return -1;
}

