public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int maxParts = 0;
    int maxMask = 1 << (n - 1); // bit i indicates split after position i
    for (int mask = 0; mask < maxMask; mask++) {
        HashSet<String> seen = new HashSet<>();
        int start = 0;
        boolean duplicate = false;
        // process splits
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) {
                String part = s.substring(start, i + 1);
                if (!seen.add(part)) {
                    duplicate = true;
                    break;
                }
                start = i + 1;
            }
        }
        if (duplicate) {
            continue;
        }
        // last part
        String lastPart = s.substring(start, n);
        if (!seen.add(lastPart)) {
            continue;
        }
        int partsCount = seen.size(); // equals number of split parts
        if (partsCount > maxParts) {
            maxParts = partsCount;
        }
    }
    return maxParts;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    final int[] max = {0};
    java.util.HashSet<String> used = new java.util.HashSet<>();
    class Backtracker {
        void dfs(int idx) {
            if (idx == s.length()) {
                if (used.size() > max[0]) {
                    max[0] = used.size();
                }
                return;
            }
            for (int end = idx + 1; end <= s.length(); end++) {
                String part = s.substring(idx, end);
                if (!used.contains(part)) {
                    used.add(part);
                    dfs(end);
                    used.remove(part);
                }
            }
        }
    }
    new Backtracker().dfs(0);
    return max[0];
}

public int maxUniqueSplit(String s) {
    // Validate input
    if (s == null || s.isEmpty() || s.length() > 16) {
        // For invalid inputs, return 0 as maximum unique splits is undefined
        return 0;
    }

    // Set to track used substrings in current partition
    java.util.Set<String> used = new java.util.HashSet<>();
    // Array to hold the maximum count found during recursion
    int[] maxParts = new int[1]; // maxParts[0] will store the best result

    // Start recursive depth-first search from index 0
    dfs(s, 0, used, 0, maxParts);

    return maxParts[0];
}

public int minOperations(String[] logs) {
