    int remaining = k - n; // amount of extra value to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int extra = Math.min(25, remaining);
        sb.setCharAt(i, (char) ('a' + extra));
        remaining -= extra;
    }
    return sb.toString();
}

