    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length n must be positive.");
    }
    int minPossible = n;          // all 'a'
    int maxPossible = 26 * n;     // all 'z'
    if (k < minPossible || k > maxPossible) {
        throw new IllegalArgumentException("k is out of possible range.");
    }
    StringBuilder sb = new StringBuilder(n);
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    int remaining = k - n;  // number of extra points to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        sb.setCharAt(i, (char) ('a' + add));
        remaining -= add;
    }
    return sb.toString();
}

