public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < 0) {
        return result;
    }
    // Handle 0 separately if within range
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    // For digits 1 through 9, generate stepping numbers via BFS
    for (int start = 1; start <= 9; start++) {
        Queue<Long> queue = new ArrayDeque<>();
        queue.offer((long) start);
        while (!queue.isEmpty()) {
            long cur = queue.poll();
            if (cur > high) {
                continue;
            }
            if (cur >= low) {
                result.add((int) cur);
            }
            long lastDigit = cur % 10;
            // Append lastDigit - 1
            if (lastDigit > 0) {
                long next = cur * 10 + (lastDigit - 1);
                if (next <= high) {
                    queue.offer(next);
                }
            }
            // Append lastDigit + 1
            if (lastDigit < 9) {
                long next = cur * 10 + (lastDigit + 1);
                if (next <= high) {
                    queue.offer(next);
                }
            }
        }
    }
    Collections.sort(result);
    return result;
}

