                    diag[i][j] = (i > 0 && j > 0 && mat[i - 1] != null && mat[i - 1].length > j - 1) ? diag[i - 1][j - 1] + 1 : 1;
                    anti[i][j] = (i > 0 && j < n - 1 && mat[i - 1] != null && mat[i - 1].length > j + 1) ? anti[i - 1][j + 1] + 1 : 1;
                    int currentMax = Math.max(Math.max(hor[i][j], ver[i][j]), Math.max(diag[i][j], anti[i][j]));
                    if (currentMax > max) max = currentMax;
                }
            }
        }
    } catch (Exception e) {
        // In case of irregular row lengths or other runtime issues, return the max found so far
        return max;
    }
    return max;
}

