public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    int max = 0;
    for (int v : A) {
        if (v > max) max = v;
    }
    int limit = max * 2;
    boolean[] isSquare = new boolean[limit + 1];
    for (int i = 0; i * i <= limit; i++) {
        isSquare[i * i] = true;
    }
    java.util.Map<Integer, Integer> freqMap = new java.util.HashMap<>();
    for (int v : A) {
        freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
    }
    int nUnique = freqMap.size();
    int[] vals = new int[nUnique];
    int[] counts = new int[nUnique];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
        vals[idx] = entry.getKey();
        counts[idx] = entry.getValue();
        idx++;
    }
    java.util.Arrays.sort(vals);
    class Rec {
        long dfs(int prev, int remaining) {
            if (remaining == 0) {
                return 1;
            }
            long total = 0;
            for (int i = 0; i < vals.length; i++) {
                if (counts[i] == 0) continue;
                if (prev == -1 || (prev + vals[i] <= limit && isSquare[prev + vals[i]])) {
                    counts[i]--;
                    total += dfs(vals[i], remaining - 1);
                    counts[i]++;
                }
            }
            return total;
        }
    }
    Rec r = new Rec();
    long result = r.dfs(-1, A.length);
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    java.util.Arrays.sort(A);
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int r = (int) Math.sqrt(sum);
            if (r * r == sum) can[i][j] = true;
        }
    }
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < n; i++) {
        if (i > 0 && A[i] == A[i - 1]) continue;
        dp[1 << i][i] = 1L;
    }
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            if ((mask & (1 << last)) == 0) continue;
            long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (!can[last][next]) continue;
                if (next > 0 && A[next] == A[next - 1] && ((mask & (1 << (next - 1))) == 0)) continue;
                int newMask = mask | (1 << next);
                dp[newMask][next] += cur;
            }
        }
    }
    long result = 0;
    for (int last = 0; last < n; last++) {
        result += dp[fullMask][last];
    }
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute perfect squares up to 2*max(A)
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) maxVal = v;
    }
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // Build adjacency list
    @SuppressWarnings("unchecked")
    java.util.ArrayList<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[A[i] + A[j]]) {
                adj[i].add(j);
            }
        }
    }
    // DP memoization
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(memo[i], -1);
    }
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int lastIndex, int mask) {
            if (mask == fullMask) return 1;
            int memoVal = memo[mask][lastIndex];
            if (memoVal != -1) return memoVal;
            int res = 0;
            java.util.HashSet<Integer> seen = new java.util.HashSet<>();
            for (int next : adj[lastIndex]) {
                if ((mask & (1 << next)) == 0) {
                    int val = A[next];
                    if (seen.contains(val)) continue;
                    seen.add(val);
                    res += this.applyAsInt(next, mask | (1 << next));
                }
            }
            memo[mask][lastIndex] = res;
            return res;
        }
    };
    int total = 0;
    java.util.HashSet<Integer> startSeen = new java.util.HashSet<>();
    for (int i = 0; i < n; i++) {
        int val = A[i];
        if (startSeen.contains(val)) continue;
        startSeen.add(val);
        total += dfs.applyAsInt(i, 1 << i);
    }
    return total;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    java.util.Arrays.sort(A);
    int fullMask = (1 << n) - 1;
    long[][] memo = new long[1 << n][n + 1];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(memo[i], -1L);
    }
    java.util.function.BiFunction<Integer, Integer, Long> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Long apply(Integer mask, Integer last) {
            int lastIndex = (last == -1) ? n : last;
            if (mask == fullMask) return 1L;
            long cached = memo[mask][lastIndex];
            if (cached != -1L) return cached;
            long total = 0L;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0) continue;
                if (j > 0 && A[j] == A[j - 1] && (mask & (1 << (j - 1))) == 0) continue;
                if (last == -1 || isPerfectSquare(A[last] + A[j])) {
                    total += this.apply(mask | (1 << j), j);
                }
            }
            memo[mask][lastIndex] = total;
            return total;
        }
    };
    long result = dfs.apply(0, -1);
    return (int) result;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) return 1;
    int n = A.length;
    // Build frequency map
    java.util.Map<Integer, Integer> freqMap = new java.util.HashMap<>();
    for (int x : A) {
        freqMap.put(x, freqMap.getOrDefault(x, 0) + 1);
    }
    // Unique values array
    int m = freqMap.size();
    int[] values = new int[m];
    int[] counts = new int[m];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> e : freqMap.entrySet()) {
        values[idx] = e.getKey();
        counts[idx] = e.getValue();
        idx++;
    }
    // Precompute adjacency matrix for values
    boolean[][] adj = new boolean[m][m];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < m; j++) {
            if (isPerfectSquare(values[i] + values[j])) {
                adj[i][j] = true;
            }
        }
    }
    // Memoization map: key = encodedCounts * (m + 1) + lastIndex
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    int base = n + 1;
    // Helper recursive function
    java.util.function.BiFunction<Integer, int[], Integer> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Integer apply(Integer lastIdx, int[] cnt) {
            // Encode state
            long key = encodeCounts(cnt, m, base) * (m + 1L) + lastIdx;
            if (memo.containsKey(key)) return memo.get(key);
            boolean finished = true;
            for (int v : cnt) {
                if (v > 0) {
                    finished = false;
                    break;
                }
            }
            if (finished) return 1;
            int total = 0;
            for (int next = 0; next < m; next++) {
                if (cnt[next] > 0 && adj[lastIdx][next]) {
                    cnt[next]--;
                    int res = dfs.apply(next, cnt);
                    total += res;
                    cnt[next]++;
                }
            }
            memo.put(key, total);
            return total;
        }
    };
    // Initial call: try each value as start
    int result = 0;
    for (int start = 0; start < m; start++) {
        if (counts[start] == 0) continue;
        counts[start]--;
        result += dfs.apply(start, counts);
        counts[start]++;
    }
    return result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = 0;
    stack[top++] = -1; // sentinel
    long maxArea = 0L;
    for (int i = 0; i < n; i++) {
        while (top > 1 && heights[stack[top - 1]] >= heights[i]) {
            int height = heights[stack[--top]];
            int width = i - stack[top - 1] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[top++] = i;
    }
    while (top > 1) {
        int height = heights[stack[--top]];
        int width = n - stack[top - 1] - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return (int) maxArea;
}

