public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find pivot: first index from end where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // Already the highest permutation
        return -1;
    }

    // Find successor: first index from end that is greater than pivot
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap pivot and successor
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse suffix starting at i+1
    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer, checking for overflow
    long result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
    }

    if (result > Integer.MAX_VALUE || result <= n) {
        return -1;
    }
    return (int) result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    // Convert integer to digit array
    int temp = n;
    int len = 0;
    while (temp > 0) {
        len++;
        temp /= 10;
    }
    if (len == 0) {
        return -1; // Should not happen for positive n
    }
    int[] digits = new int[len];
    temp = n;
    for (int i = len - 1; i >= 0; i--) {
        digits[i] = temp % 10;
        temp /= 10;
    }

    // Find the longest non-increasing suffix
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // No higher permutation
    }

    // Find the rightmost successor to pivot
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap pivot with successor
    int tmp = digits[i];
    digits[i] = digits[j];
    digits[j] = tmp;

    // Reverse suffix
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        tmp = digits[left];
        digits[left] = digits[right];
        digits[right] = tmp;
        left++;
        right--;
    }

    // Convert back to integer, checking for overflow
    long result = 0;
    for (int d : digits) {
        result = result * 10 + d;
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
    }

    return (int) result;
}

