    };

    char[] current = new char[n];

    // Helper recursive method
    java.util.function.BiConsumer<Integer, Integer> dfs = new java.util.function.BiConsumer<Integer, Integer>() {
        @Override
        public void accept(Integer left, Integer right) {
            if (left > right) {
                result.add(new String(current));
                return;
            }
            if (left == right) { // middle digit for odd length
                for (char middle : new char[]{'0', '1', '8'}) {
                    current[left] = middle;
                    result.add(new String(current));
                }
                return;
            }
            for (char[] pair : pairs) {
                // Skip leading zero unless the number length is 1
                if (left == 0 && pair[0] == '0' && n > 1) {
                    continue;
                }
                current[left] = pair[0];
                current[right] = pair[1];
                accept(left + 1, right - 1);
            }
        }
    };

    try {
        dfs.accept(0, n - 1);
    } catch (Exception e) {
        // In case of unexpected runtime issues, return what has been collected so far
        return result;
    }

    return result;
}

