        }
    }
    new Helper().dfs(0);
    java.util.Collections.sort(result);
    return result;
}

public static boolean isBoomerang(int[][] points) {
    // Validate input
    if (points == null || points.length != 3) {
        return false;
    }
    try {
        for (int i = 0; i < 3; i++) {
            if (points[i] == null || points[i].length != 2) {
                return false;
            }
        }
    } catch (Exception e) {
        // Any unexpected exception leads to false
        return false;
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Calculate twice the area of the triangle using cross product
    int areaTwice = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    // If areaTwice is zero, points are collinear => not a boomerang
    return areaTwice != 0;
}

public static boolean isBoomerang(int[][] points) {
