        long area = (long)(x2 - x1) * (y3 - y1) - (long)(x3 - x1) * (y2 - y1);

        // If area is zero, points are collinear (or duplicate), not a boomerang
        return area != 0;
    } catch (Exception e) {
        // If any unexpected issue occurs (e.g., array access), treat as not a boomerang
        return false;
    }
}

