public static java.util.List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>(n > 0 ? n : 0);
    if (n <= 0) {
        return result; // Return empty list for non-positive n
    }
    try {
        int current = 1;
        while (result.size() < n) {
