            if (current <= n / 10) { // Can go deeper
                current *= 10;
            } else if (current % 10 != 9 && current + 1 <= n) { // Move to next sibling
                current++;
            } else { // Need to backtrack
                while (current % 10 == 9 && current / 10 > 0) {
                    current /= 10;
                }
                current++;
            }
        }
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return the achieved result so far
    }
    return result;
}

