public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // maximum number of 1^2 needed
        for (int k = 1; k * k <= i; k++) {
            int square = k * k;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // worst case: all 1^2
        int j = 1;
        while (j * j <= i) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
            j++;
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0; // Or throw new IllegalArgumentException("n must be positive");
    }
    int[] dp = new int[n + 1];
    // Initialize dp with a large number
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int s = 1; s * s <= i; s++) {
            int square = s * s;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    // Trim leading/trailing spaces to avoid empty tokens at ends
    String trimmed = s.trim();
    if (trimmed.isEmpty()) {
        // Preserve the original string's length of spaces if any
        return s;
    }
    String[] words = trimmed.split("\\s+");
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        sb.append(new StringBuilder(words[i]).reverse());
        if (i != words.length - 1) {
            sb.append(' ');
        }
    }
    return sb.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    try {
        String[] words = s.split(" ");
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            result.append(new StringBuilder(words[i]).reverse());
            if (i < words.length - 1) {
                result.append(' ');
            }
        }
        return result.toString();
    } catch (Exception e) {
        // Unexpected runtime issue; return null as safe fallback
        return null;
    }
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    try {
        int n = s.length();
        StringBuilder result = new StringBuilder(n);
        StringBuilder word = new StringBuilder();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == ' ') {
                result.append(word.reverse());
                result.append(' ');
                word.setLength(0);
            } else {
                word.append(c);
            }
        }
        if (word.length() > 0) {
            result.append(word.reverse());
        }
        return result.toString();
    } catch (Exception e) {
        // In case of unexpected errors, return the original string
        return s;
    }
}

